<?php require_once __DIR__ . '/../controller/Auth.php'; $currentUser = requireRole('psicologo'); ?>
<?php require_once __DIR__ . '/../controller/DadosController.php'; $d=loadPageData(basename(__FILE__),$currentUser);
require_once __DIR__ . '/componentes/componentes.php'; require_once __DIR__ . '/componentes/dados.php'; ?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><link rel="stylesheet" href="../css/componentes.css"><link rel="stylesheet" href="../css/prontuarioPsicologo.css"><title>Mindly | Prontuários</title></head><body><?php abrirLayout('psicologo','prontuarios','Prontuário digital','Registre e acompanhe informações dos atendimentos.',$currentUser['nome']); ?>
<div class="pront-grid"><aside class="cartao lista-pacientes"><div class="busca"><?= icon('users') ?><strong>Pacientes vinculados</strong></div><?php foreach($d['pacientes'] as $p): ?><a class="paciente-item <?= ($d['paciente']['id'] ?? null)===$p['id']?'ativo':'' ?>" href="<?= e(publicLink('prontuarioPsicologo.php',$p['id'],'paciente_id')) ?>"><span class="avatar-foto"><?= e(initials($p['nome'])) ?></span><div><strong><?= e($p['nome']) ?></strong><small><?= (int)$p['sessoes'] ?> sessões</small></div></a><?php endforeach; if(!$d['pacientes']) emptyState('Nenhum paciente vinculado até o momento.'); ?></aside><section class="cartao prontuario"><div class="cabecalho-paciente"><div class="ident"><span class="avatar-foto grande"><?= e(initials($d['paciente']['nome'] ?? '')) ?></span><div><h2><?= e($d['paciente']['nome'] ?? 'Selecione um paciente') ?></h2><span>Registros restritos ao profissional responsável</span></div></div><button class="botao botao-principal" disabled><?= icon('plus') ?> Novo registro</button></div><?php unavailable('Criação e edição de prontuários'); ?>
<?php if($p=$d['paciente']): ?><div class="metricas"><div><span>Sessões realizadas</span><strong><?= (int)$p['sessoes'] ?></strong></div><div><span>Último registro</span><strong><?= dateLabel($d['registros'][0]['inicio_em'] ?? null,'d/m/Y') ?></strong></div><div><span>Próxima consulta</span><strong><?= dateLabel($p['proxima']) ?></strong></div></div><?php endif; ?>
<?php foreach($d['registros'] as $r): ?><div class="registro-atual"><div class="registro-topo"><div><span><?= dateLabel($r['inicio_em']) ?></span><h3>Registro do atendimento</h3></div><button disabled title="Edição ainda não disponível"><?= icon('edit') ?></button></div><div class="campo"><label>Observações do atendimento</label><textarea readonly><?= e($r['observacoes']) ?></textarea></div><div class="registro-rodape"><span><?= icon('shield') ?> Informação confidencial · Atualizado em <?= dateLabel($r['atualizado_em']) ?></span><button class="botao botao-principal" disabled>Salvar registro</button></div></div><?php endforeach; if(!$d['registros']) emptyState('Nenhum registro disponível até o momento.'); ?></section></div>
<?php fecharLayout(); ?></body></html>
